function verify(st){var m=/^SIG-(\d{6})-(\d{1,3})$/.exec(st); if(!m)return false; var n=parseInt(m[1],10);
 var h=0; var s='SIG-'+m[1]; for(var i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0; return (h%997)===parseInt(m[2],10);}
